@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-editable-cell {
  position: relative;
  width: min(240px, 100%);
  min-width: 0;
}

.whatiuse-editable-cell__trigger,
.whatiuse-editable-cell__form {
  display: flex;
  width: 100%;
  min-width: 0;
  min-height: 32px;
  align-items: center;
  gap: 8px;
  border: 1px solid transparent;
  border-radius: var(--whatiuse-radius-control);
  background: transparent;
  color: var(--whatiuse-fg-default);
}

.whatiuse-editable-cell__trigger {
  justify-content: space-between;
  padding: 0 8px;
  font: inherit;
  text-align: start;
  cursor: text;
  transition: background-color 140ms var(--whatiuse-ease-out), border-color 140ms var(--whatiuse-ease-out);
}

.whatiuse-editable-cell__trigger > span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.whatiuse-editable-cell__trigger > svg { width: 13px; height: 13px; flex: 0 0 auto; color: var(--whatiuse-fg-subtle); opacity: 0; transition: opacity 140ms var(--whatiuse-ease-out); }

.whatiuse-editable-cell__trigger:disabled { cursor: default; opacity: .52; }

.whatiuse-editable-cell__form {
  padding: 2px;
  border-color: var(--whatiuse-control-border-hover);
  background: var(--whatiuse-bg-surface);
  box-shadow: var(--whatiuse-shadow-control);
}

.whatiuse-editable-cell__input {
  width: 100%;
  min-width: 0;
  height: 26px;
  padding: 0 6px;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--whatiuse-fg-default);
  font: inherit;
}

.whatiuse-editable-cell__actions { display: flex; flex: 0 0 auto; align-items: center; gap: 1px; }

.whatiuse-editable-cell__actions .whatiuse-icon-button { width: 26px; height: 26px; min-height: 26px; padding: 0; }

.whatiuse-editable-cell__actions svg { width: 12px; height: 12px; }

.whatiuse-editable-cell__error {
  position: absolute;
  z-index: var(--whatiuse-layer-flyout);
  top: calc(100% + 4px);
  left: 0;
  display: none;
  max-width: 280px;
  padding: 5px 7px;
  border-radius: 6px;
  background: var(--whatiuse-bg-flyout);
  color: var(--whatiuse-fg-danger);
  box-shadow: var(--whatiuse-shadow-flyout);
  font-size: var(--whatiuse-type-metadata);
  white-space: nowrap;
}

.whatiuse-editable-cell__error:not(:empty) { display: block; }

@media (hover: hover) and (pointer: fine) {
.whatiuse-editable-cell__trigger:not(:disabled):hover { border-color: color-mix(in oklch, var(--whatiuse-control-border) 62%, transparent); background: var(--whatiuse-hover); }

.whatiuse-editable-cell__trigger:not(:disabled):hover > svg { opacity: 1; }
}

@media (prefers-reduced-motion: reduce) {
.whatiuse-editable-cell__trigger,
.whatiuse-editable-cell__trigger > svg { transition: none; }
}
}
